class ModelValidationResult:
    def __init__(
        self,
        success: bool,
        model: Any = None,
        errors: Optional[Dict[str, str]] = None
    ):
        self.success = success
        self.model = model
        self.errors = errors or {}

def validate_model_from_json(
    input_json: Dict[str, Any],
    model_class: type[BaseModel],
    config: "BaseSettings" = None
) -> ModelValidationResult:
    """
    Validate a JSON input against a Pydantic model.

    Args:
        input_json: The JSON input to validate.
        model_class: The Pydantic model class to validate against.
        config: Optional configuration (e.g., from `pyproject.toml`).

    Returns:
        A `ModelValidationResult` object containing the outcome of validation.
    """
    if not validate_json(input_json):
        return ModelValidationResult(False, errors={"input": "Invalid JSON provided"})

    try:
        model = model_class(**input_json)
        model.validate()
    except Exception as e:
        # Use Pydantic's error handling to extract and format errors
        if isinstance(e, ValueError):
            error_messages = {
                field: error['msg']
                for field, error in e.errors().items()
            }
            return ModelValidationResult(False, errors=error_messages)
        else:
            log_error(f"Unexpected error validating model: {e}")
            return ModelValidationResult(False, errors={"error": str(e)})

    return ModelValidationResult(True, model=model)

