# Function to run the validation task
def run_model_validation(json_input: str, model_class: type[BaseModel] = ExampleModel) -> None:
    """Main function to validate a JSON input into a model."""
    config = load_config()

    # Parse JSON input
    try:
        input_json = json.loads(json_input)
    except json.JSONDecodeError:
        log_error("Invalid JSON format")
        return

    # Validate model
    result = validate_model_from_json(input_json, model_class, config)

    if result.success:
        log_info("Validation successful")
        log_info(f"Model instance: {result.model}")
    else:
        log_error("Validation failed")
        for field, error in result.errors.items():
            log_error(f"Field: {field}, Error: {error}")

