def print_aligned_table(records, headers=None):
    if headers is None:
        headers = records[0].keys() if records else []
    else:
        headers = headers

    # Get the maximum width for each column
    column_widths = [max(len(str(record.get(header, ''))) for record in records) for header in headers]

    # Format each row
    for record in records:
        row = []
        for header, width in zip(headers, column_widths):
            row.append(str(record.get(header, '')).ljust(width))
        print(''.join(row))

