def format_field(field: str, align: str, width: int) -> str:
    """
    Format a field to fit within a column of the given width and alignment.
    """
    field_str = str(field)
    if align == "left":
        return field_str.ljust(width)
    elif align == "right":
        return field_str.rjust(width)
    elif align == "center":
        return field_str.center(width)
    else:
        raise ValueError(f"Invalid alignment: {align}. Use 'left', 'right', or 'center'.")

