@click.option("--verify", type=str, help="Path to a file with the stored hash")
def password_hashing(password: str, hash: bool, verify: Optional[str] = None):
    """
    Securely hash a password or verify a password against a stored hash.

    If --hash is passed, it will hash the password and return it
    If --verify is passed, the password will be verified against the stored hash
    """
    if hash:
        hashed = hash_password(password)
        click.echo(f"Hashed password: {hashed}")
        click.echo("Store this hash securely!")

    elif verify:
        if not Path(verify).exists():
            click.echo(f"File {verify} not found. Cannot verify.")
            return

        try:
            with open(verify, "r") as file:
                stored_hash = file.read().strip()
        except Exception as e:
            click.echo(f"Error reading hash file: {e}")
            return

        if verify_password(password, stored_hash):
            click.echo("✅ Password is valid!")
        else:
            click.echo("❌ Invalid password.")

    else:
        click.echo("Use --hash to hash a password or --verify <file> to check a password against a stored hash.")

